package ru.livingvillages;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import ru.livingvillages.domain.*;
import ru.livingvillages.persistence.Database;
import java.nio.file.Path;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class NewSettlementTest {
    @TempDir Path directory;
    
    
    @Test void pendingIrrigationTakesPriorityOverIronToolsAndOtherCoreConstruction() throws Exception {var v=AutonomyData.village();var rules=AutonomyData.rules();AutonomyData.building(v,"stone_pit","stone_pit").resourceLeft=40;AutonomyData.building(v,"kiln_house",null,"furnace");var exhausted=AutonomyData.building(v,"iron_pit","iron_pit");exhausted.resourceLeft=0;var field=AutonomyData.building(v,"garden","garden");field.complete=false;var pending=new Village.Project();pending.kind="garden";pending.building=field.id;pending.required.put("WATER_BUCKET",1);v.projects.add(pending);var home=AutonomyData.building(v,"family_home",null);home.complete=false;var housing=new Village.Project();housing.kind="family_home";housing.building=home.id;housing.required.put("WHITE_BED",2);v.projects.add(housing);v.nutrition=.8;assertTrue(Assembly.rawDemand(v,rules).getOrDefault("RAW_IRON",0)>0);assertEquals("water_intake",Autonomy.next(v,rules));assertEquals("water_intake",Autonomy.foodRecovery(v,rules));}
    @Test void immigrationKeepsThreeDaysOfFoodForTheNewResidentToo() throws Exception {var rules=AutonomyData.rules();rules.autonomy=false;rules.foods.clear();rules.foods.put("CARROT",2);var v=AutonomyData.village();v.days=3;v.laws.immigration=true;v.stock.items.clear();v.stock.add("CARROT",30,v.capacity);v.buildings.stream().filter(b->b.recipe!=null).forEach(b->b.resourceConfirmed=false);new Simulation(rules).day(v);assertEquals(5,v.living(),"after consumption there are 40 food units, insufficient even for the existing reserve");v.stock.items.clear();v.stock.add("CARROT",43,v.capacity);v.days=7;new Simulation(rules).day(v);assertEquals(5,v.living(),"66 after consumption meets the old 60 but not the prospective 72");v.stock.add("CARROT",13,v.capacity);v.days=11;new Simulation(rules).day(v);assertEquals(6,v.living());}
    @Test void upperFloorReferencesSurviveSavingWithoutTreatingTheRoofAsAStorey(){var v=new Village();var b=new Village.Building();b.kind="family_home";b.complete=true;b.x=0;b.z=0;b.width=7;b.depth=7;b.workY=2;v.buildings.add(b);var project=new Village.Project();project.building=b.id;project.state="COMPLETE";v.projects.add(project);var ground=new Village.Block(1,1,3,1,"minecraft:air","minecraft:oak_planks",null);var upper=new Village.Block(1,5,3,2,"minecraft:air","minecraft:oak_planks",null);upper.floor=true;project.blocks.addAll(List.of(ground,upper,new Village.Block(1,9,3,3,"minecraft:air","minecraft:oak_planks",null)));var restored=Database.copy(v);assertTrue(Projects.expected(restored,b.id).stream().anyMatch(c->c.floor && c.y==5));assertEquals(5,Shelters.floors(v,b,1.5,6,3.5,4).getFirst().y);assertEquals(1,Shelters.floors(v,b,1.5,2,3.5,4).getFirst().y);assertTrue(Shelters.floors(v,b,1.5,10,3.5,4).stream().noneMatch(c->c.y==9));}
    @Test void losingTheGuardCannotTakeTheLastBuilderOrMerchant(){var v=new Village();for(var role:List.of(Village.Role.ELDER,Village.Role.MERCHANT,Village.Role.FARMER,Village.Role.BUILDER,Village.Role.GUARD,Village.Role.CHILD)){var r=new Village.Resident();r.role=role;if(role==Village.Role.GUARD)r.alive=false;if(role==Village.Role.CHILD)r.matureDay=8;v.residents.add(r);}Simulation.electReplacement(v);assertEquals(1,Jobs.builders(v));assertTrue(v.residents.stream().anyMatch(r->r.role==Village.Role.MERCHANT && r.alive));assertTrue(v.residents.stream().noneMatch(r->r.role==Village.Role.GUARD && r.alive));}
    @Test void secondFarmCannotStealTheLastAdultBuilderEvenWhenAChildHasThatLegacyRole() throws Exception {var v=AutonomyData.village();var rules=AutonomyData.rules();var builder=new Village.Resident();builder.role=Village.Role.BUILDER;v.residents.add(builder);var child=new Village.Resident();child.role=Village.Role.BUILDER;child.matureDay=8;v.residents.add(child);AutonomyData.building(v,"garden","garden");Vitals.reconcile(v,rules);for(int i=0;i<20;i++)Jobs.fill(v,rules);assertEquals(Village.Role.BUILDER,builder.role);assertNull(builder.workplace);assertEquals(Village.Role.CHILD,child.role);assertNull(child.workplace);assertEquals(1,Jobs.builders(v));}
    @Test void oldDuplicateFarmersReleaseAnAdultForConstruction() throws Exception {var v=AutonomyData.village();var rules=AutonomyData.rules();var extra=new Village.Resident();extra.role=Village.Role.FARMER;extra.workplace=AutonomyData.building(v,"garden","garden").id;v.residents.add(extra);Jobs.fill(v,rules);assertEquals(1,Jobs.builders(v));assertTrue(v.residents.stream().anyMatch(r->r.role==Village.Role.FARMER && r.workplace!=null));}
    @Test void aChildNeeds160MinutesAndPausingDoesNotMatureIt(){var v=new Village();var child=new Village.Resident();child.role=Village.Role.BUILDER;child.matureDay=8;v.residents.add(child);var rules=new Rules();assertEquals(160,Population.maturityMinutes(v,child,rules));v.paused=true;new Simulation(rules).elapse(v,3_600_000,9);assertEquals(160,Population.maturityMinutes(v,child,rules));v.paused=false;v.days=8;Vitals.reconcile(v,rules);assertEquals(Village.Role.BUILDER,child.role);assertTrue(v.adult(child));}
    @Test void newHousingAttractsARealAdultNextDayEvenWhenOldResidentsMovedIntoIt() throws Exception {var rules=AutonomyData.rules();rules.childImmigrationPercent=100;var plain=AutonomyData.village();plain.laws.immigration=true;plain.lastImmigrationDay=0;plain.stock.add("CARROT",500,plain.capacity);var housed=Database.copy(plain);var home=AutonomyData.building(housed,"family_home",null);home.beds=2;new Simulation(rules).day(plain);new Simulation(rules).day(housed);assertEquals(5,plain.living());assertEquals(6,housed.living());assertTrue(housed.adult(housed.residents.getLast()));assertEquals(1,Jobs.builders(housed));}
    @Test void aRealEmptyFamilyHomeShortensArrivalInterval(){var v=new Village();v.days=1;v.lastImmigrationDay=0;var r=new Rules();assertFalse(Population.arrivalDue(v,r));var home=new Village.Building();home.kind="family_home";home.beds=2;home.complete=true;v.buildings.add(home);assertTrue(Population.arrivalDue(v,r));home.damaged=true;assertFalse(Population.arrivalDue(v,r));}
    @Test void aNewcomerIsNotHostileButActualAggressionBelow50Is(){var v=new Village();var player=UUID.randomUUID();var r=new Rules();assertFalse(Population.hostile(v,player,r));v.relation(player).trust=55;Social.harm(v,player,UUID.randomUUID(),r,false);assertEquals(50,v.relation(player).trust);assertFalse(Population.hostile(v,player,r));Social.harm(v,player,UUID.randomUUID(),r,false);assertTrue(Population.hostile(v,player,r));int before=v.relation(player).trust;Social.harm(v,player,UUID.randomUUID(),r,true);assertEquals(before-100,v.relation(player).trust);}
    @Test void layoutsAreRepeatableButNotTenCopiesOfOneSquare(){var shapes=List.of(new Layouts.Shape("hall",-18,-14,11,11),new Layouts.Shape("warehouse",1,-14,9,9),new Layouts.Shape("garden",-18,2,11,11));var signatures=new HashSet<List<Layouts.Plot>>();for(int i=0;i<40;i++){var seed=new UUID(13,i);var plan=Layouts.arrange(shapes,seed,0);assertEquals(plan,Layouts.arrange(shapes,seed,0));signatures.add(plan);}assertTrue(signatures.size()>=32);}
    
    
    
    
    
    
}
